// Required Constants (assumed defined in calling context)
// IOBASE_MEMORY, IOBASE_IO, ERROR_NO_RESOURCE

unsigned long target_bus = 1;
unsigned long target_devfn = 0x2000; // D:4, F:0
unsigned long phys_addr;

// 1. Retrieve the physical base address for the MMIO region
phys_addr = pciconfig_iobase(
    IOBASE_MEMORY,
    target_bus,
    target_devfn
);

// Common Error Check: A zero return often means the
// requested resource (BAR) does not exist or 'which' is invalid.
if (phys_addr == 0) {
    // Handle error or resource not found
    return ERROR_NO_RESOURCE;
}

// 2. Retrieve IO port region
unsigned long io_port = pciconfig_iobase(IOBASE_IO, target_bus, target_devfn);
